import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class B {
	static PrintWriter out = new PrintWriter(System.out);


	public static void main(String[] args) {
		FS in = new FS();
		long R = in.nextLong();
		long C = in.nextLong();
		long res = solve(Math.min(R, C), Math.max(R, C));
		out.println(res);
		out.close();
	}

	static long solve(long r, long c) {
		if(r < 3 && c < 3) return 0;
		if(r == 1) {
			long res = c;
			long m = c%6;
			if(m != 0) {
				if(m <= 3) res -= m;
				if(m == 4) res -= 2;
				if(m == 5) res -= 1;
			}
			return res;
		}
		if(r == 2) {
			if(c == 3 || c == 7) return r * (c-1);
			return r*c;
		}
		long res = r*c;
		if(res%2 == 0) return res;
		return res-1;
	}

